package io.knowledgebrain.space;
import com.google.protobuf.ByteString;
import java.security.MessageDigest;
import java.sql.*;
import java.time.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;
final class GroupMembershipStore {
 record Member(UUID groupId,UUID spaceId,UUID principalId,String role,String state,long version){}
 record Invitation(UUID invitationId,UUID groupId,UUID spaceId,UUID creatorPrincipalId,String role,String state,long version,Instant createdAt,Instant expiresAt,UUID acceptedPrincipalId){}
 record Issued(Invitation invitation,String code){@Override public String toString(){return "Issued[REDACTED]";}}
 record MemberRevision(long version,String role,String state,UUID actorId,Instant occurredAt,String reason,UUID invitationId){}
 record InvitationRevision(long version,String state,UUID actorId,Instant occurredAt,UUID acceptedPrincipalId){}
 record Context(UUID groupId,UUID spaceId,UUID owner){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final Clock clock;private final UuidV7 ids;private final GroupInvitationCodes codes;
 GroupMembershipStore(DataSource source,Clock clock,GroupInvitationCodes codes){jdbc=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);this.codes=codes;}
 private ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Group unavailable");}
 private ResponseStatusException conflict(String message){return new ResponseStatusException(HttpStatus.CONFLICT,message);}
 private ResponseStatusException gone(){return new ResponseStatusException(HttpStatus.GONE,"Invitation unavailable");}
 private Context context(UUID group,boolean lock){var rows=jdbc.query("SELECT g.group_id,s.space_id,s.owner_principal_id FROM group_space_origin g JOIN space s ON s.space_id=g.space_id WHERE g.group_id=? AND s.kind='GROUP' AND s.visibility='PRIVATE' AND s.state='ACTIVE'"+(lock?" FOR UPDATE OF s":""),(rs,n)->new Context(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getObject(3,UUID.class)),group);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private Member member(Context group,UUID principal){var rows=jdbc.query("SELECT role,state,group_version FROM space_membership WHERE space_id=? AND principal_id=?",(rs,n)->new Member(group.groupId(),group.spaceId(),principal,rs.getString(1),rs.getString(2),rs.getLong(3)),group.spaceId(),principal);return rows.isEmpty()?null:rows.getFirst();}
 private Member active(Context group,UUID principal){var m=member(group,principal);if(m==null||!m.state().equals("ACTIVE")||!Set.of("OWNER","MEMBER","VIEWER").contains(m.role()))throw missing();return m;}
 private void owner(Context group,UUID actor){var m=active(group,actor);if(!group.owner().equals(actor)||!m.role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Group OWNER required");}
 private void expected(long version,long actual){if(version!=actual)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Group version changed");}
 static void role(String role){if(!Set.of("MEMBER","VIEWER").contains(Optional.ofNullable(role).orElse("")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"MEMBER or VIEWER required");}
 Member self(UUID group,UUID actor){return active(context(group,false),actor);}
 List<Member> members(UUID group,UUID actor,UUID after,int limit){var c=context(group,false);owner(c,actor);return jdbc.query("SELECT principal_id,role,state,group_version FROM space_membership WHERE space_id=? AND state='ACTIVE' AND principal_id>? ORDER BY principal_id LIMIT ?",(rs,n)->new Member(group,c.spaceId(),rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3),rs.getLong(4)),c.spaceId(),after==null?new UUID(0,0):after,limit+1);}
 List<MemberRevision> memberHistory(UUID group,UUID actor,UUID principal,long before,int limit){var c=context(group,false);owner(c,actor);if(member(c,principal)==null)throw missing();return jdbc.query("SELECT * FROM group_membership_revision WHERE space_id=? AND principal_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new MemberRevision(rs.getLong("version"),rs.getString("role"),rs.getString("state"),rs.getObject("actor_id",UUID.class),rs.getTimestamp("occurred_at").toInstant(),rs.getString("reason"),rs.getObject("invitation_id",UUID.class)),c.spaceId(),principal,before,limit+1);}
 private Invitation invitation(ResultSet rs)throws SQLException{return new Invitation(rs.getObject("invitation_id",UUID.class),rs.getObject("group_id",UUID.class),rs.getObject("space_id",UUID.class),rs.getObject("creator_principal_id",UUID.class),rs.getString("role"),rs.getString("state"),rs.getLong("version"),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("expires_at").toInstant(),rs.getObject("accepted_principal_id",UUID.class));}
 private Invitation find(UUID space,UUID id){var rows=jdbc.query("SELECT * FROM group_invitation WHERE space_id=? AND invitation_id=?",(rs,n)->invitation(rs),space,id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Invitation unavailable");return rows.getFirst();}
 private Invitation effective(Invitation i){return i.state().equals("PENDING")&&!i.expiresAt().isAfter(clock.instant())?new Invitation(i.invitationId(),i.groupId(),i.spaceId(),i.creatorPrincipalId(),i.role(),"EXPIRED",i.version(),i.createdAt(),i.expiresAt(),null):i;}
 List<Invitation> invitations(UUID group,UUID actor,UUID after,int limit){var c=context(group,false);owner(c,actor);return jdbc.query("SELECT * FROM group_invitation WHERE space_id=? AND invitation_id>? ORDER BY invitation_id LIMIT ?",(rs,n)->effective(invitation(rs)),c.spaceId(),after==null?new UUID(0,0):after,limit+1);}
 List<InvitationRevision> invitationHistory(UUID group,UUID actor,UUID id,long before,int limit){var c=context(group,false);owner(c,actor);find(c.spaceId(),id);return jdbc.query("SELECT * FROM group_invitation_revision WHERE invitation_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new InvitationRevision(rs.getLong("version"),rs.getString("state"),rs.getObject("actor_id",UUID.class),rs.getTimestamp("occurred_at").toInstant(),rs.getObject("accepted_principal_id",UUID.class)),id,before,limit+1);}
 Issued issue(UUID group,UUID actor,String key,String role,String trace){role(role);return tx.execute(status->{var c=context(group,true);owner(c,actor);
  var prior=jdbc.query("SELECT * FROM group_invitation WHERE space_id=? AND creator_principal_id=? AND request_key=?",(rs,n)->invitation(rs),c.spaceId(),actor,key);
  if(!prior.isEmpty()){var i=prior.getFirst();if(!i.role().equals(role))throw conflict("Request key already used for another invitation role");var effective=effective(i);if(!effective.state().equals("PENDING"))return new Issued(effective,null);var code=codes.generate(i.invitationId());var saved=jdbc.queryForObject("SELECT code_hash FROM group_invitation WHERE invitation_id=?",byte[].class,i.invitationId());if(!MessageDigest.isEqual(saved,GroupInvitationCodes.hash(code)))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Invitation key changed; revoke the invitation and issue a new one");return new Issued(i,code);}
  var id=ids.next();var code=codes.generate(id);var now=clock.instant();
  jdbc.update("INSERT INTO group_invitation(invitation_id,group_id,space_id,creator_principal_id,request_key,code_hash,role,state,version,created_at,expires_at) VALUES (?,?,?,?,?,?,?,'PENDING',1,?,?)",id,group,c.spaceId(),actor,key,GroupInvitationCodes.hash(code),role,Timestamp.from(now),Timestamp.from(now.plus(Duration.ofHours(24))));var i=find(c.spaceId(),id);recordInvitation(i,actor,"GroupInvitationIssued",trace);return new Issued(i,code);
 });}
 Invitation revoke(UUID group,UUID actor,UUID id,long version,String trace){return tx.execute(status->{var c=context(group,true);owner(c,actor);var i=find(c.spaceId(),id);expected(version,i.version());if(i.state().equals("REVOKED"))return i;if(!i.state().equals("PENDING"))throw conflict("Accepted invitation cannot be revoked; remove the member instead");jdbc.update("UPDATE group_invitation SET state='REVOKED',version=2 WHERE invitation_id=?",id);var revoked=find(c.spaceId(),id);recordInvitation(revoked,actor,"GroupInvitationRevoked",trace);return revoked;});}
 Member accept(UUID actor,String code,String trace){if(!GroupInvitationCodes.valid(code))throw gone();return tx.execute(status->{
  var found=jdbc.query("SELECT * FROM group_invitation WHERE code_hash=?",(rs,n)->invitation(rs),GroupInvitationCodes.hash(code));if(found.isEmpty())throw gone();var c=context(found.getFirst().groupId(),true);var i=find(c.spaceId(),found.getFirst().invitationId());
  if(i.state().equals("ACCEPTED")){if(!actor.equals(i.acceptedPrincipalId()))throw gone();return active(c,actor);}
  if(!effective(i).state().equals("PENDING"))throw gone();var current=member(c,actor);if(current!=null&&current.state().equals("ACTIVE"))throw conflict("Already a Group member");
  jdbc.update("INSERT INTO space_membership(space_id,principal_id,role,state,group_version) VALUES (?,?,?,'ACTIVE',1) ON CONFLICT(space_id,principal_id) DO UPDATE SET role=EXCLUDED.role,state='ACTIVE',group_version=space_membership.group_version+1",c.spaceId(),actor,i.role());
  jdbc.update("UPDATE group_invitation SET state='ACCEPTED',version=2,accepted_principal_id=? WHERE invitation_id=?",actor,i.invitationId());var accepted=find(c.spaceId(),i.invitationId());recordInvitation(accepted,actor,"GroupInvitationAccepted",trace);var m=active(c,actor);recordMember(m,actor,"JOINED",i.invitationId(),trace);return m;
 });}
 Member change(UUID group,UUID actor,UUID target,long version,String role,String trace){role(role);return tx.execute(status->{var c=context(group,true);owner(c,actor);var m=active(c,target);if(m.role().equals("OWNER")||target.equals(c.owner()))throw conflict("Group OWNER is protected");expected(version,m.version());if(m.role().equals(role))return m;jdbc.update("UPDATE space_membership SET role=?,group_version=group_version+1 WHERE space_id=? AND principal_id=?",role,c.spaceId(),target);var changed=active(c,target);recordMember(changed,actor,"ROLE_CHANGED",null,trace);return changed;});}
 Member retire(UUID group,UUID actor,UUID target,long version,boolean leave,String trace){return tx.execute(status->{var c=context(group,true);if(!leave)owner(c,actor);else if(!actor.equals(target))throw missing();var m=active(c,target);if(m.role().equals("OWNER")||target.equals(c.owner()))throw conflict("Group OWNER cannot leave or be removed");expected(version,m.version());jdbc.update("UPDATE space_membership SET state='RETIRED',group_version=group_version+1 WHERE space_id=? AND principal_id=?",c.spaceId(),target);var retired=member(c,target);recordMember(retired,actor,leave?"LEFT":"REMOVED",null,trace);return retired;});}
 private void recordInvitation(Invitation i,UUID actor,String type,String trace){var now=clock.instant();jdbc.update("INSERT INTO group_invitation_revision(invitation_id,version,state,actor_id,occurred_at,accepted_principal_id) VALUES (?,?,?,?,?,?)",i.invitationId(),i.version(),i.state(),actor,Timestamp.from(now),i.acceptedPrincipalId());
  var payload=io.knowledgebrain.contracts.space.group.invitation.v1.GroupInvitationSnapshotV1.newBuilder().setInvitationId(i.invitationId().toString()).setGroupId(i.groupId().toString()).setSpaceId(i.spaceId().toString()).setCreatorPrincipalId(i.creatorPrincipalId().toString()).setRole(i.role()).setState(i.state()).setVersion(i.version()).setCreatedAtEpochMillis(i.createdAt().toEpochMilli()).setExpiresAtEpochMillis(i.expiresAt().toEpochMilli());if(i.acceptedPrincipalId()!=null)payload.setAcceptedPrincipalId(i.acceptedPrincipalId().toString());
  var event=ids.next();var envelope=io.knowledgebrain.contracts.space.group.invitation.v1.EventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("space-service").setAggregateType("GroupInvitation").setAggregateId(i.invitationId().toString()).setSpaceId(i.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(ByteString.copyFrom(payload.build().toByteArray())).build();outbox(event,"group-invitation",i.invitationId(),type,now,trace,"group-invitation-events",envelope.toByteArray());
 }
 private void recordMember(Member m,UUID actor,String reason,UUID invitation,String trace){var now=clock.instant();jdbc.update("INSERT INTO group_membership_revision(space_id,principal_id,version,role,state,actor_id,occurred_at,reason,invitation_id) VALUES (?,?,?,?,?,?,?,?,?)",m.spaceId(),m.principalId(),m.version(),m.role(),m.state(),actor,Timestamp.from(now),reason,invitation);
  var payload=io.knowledgebrain.contracts.space.group.membership.v1.GroupMembershipSnapshotV1.newBuilder().setGroupId(m.groupId().toString()).setSpaceId(m.spaceId().toString()).setPrincipalId(m.principalId().toString()).setRole(m.role()).setState(m.state()).setVersion(m.version()).setReason(reason);if(invitation!=null)payload.setInvitationId(invitation.toString());
  var event=ids.next();var envelope=io.knowledgebrain.contracts.space.group.membership.v1.EventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType("GroupMembershipChanged").setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("space-service").setAggregateType("GroupMembership").setAggregateId(m.spaceId().toString()).setSpaceId(m.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(ByteString.copyFrom(payload.build().toByteArray())).build();outbox(event,"group-membership",m.spaceId(),"GroupMembershipChanged",now,trace,"group-membership-events",envelope.toByteArray());
 }
 private void outbox(UUID event,String aggregate,UUID id,String type,Instant now,String trace,String artifact,byte[] bytes){jdbc.update("INSERT INTO outbox_event(id,aggregatetype,aggregateid,type,occurred_at,trace_id,schema_group,schema_artifact,schema_version,payload) VALUES (?,?,?,?,?,?,'space',?,'1',?)",event,aggregate,id,type,Timestamp.from(now),trace,artifact,bytes);}
}
